<script setup lang="ts">
import TableSortHeader from '@/components/TableSortHeader.vue'
import TablePager from '@/components/TablePager.vue'
import {useClientTable} from '@/features/table/useClientTable'
import {useColumnWidths} from '@/features/table/useColumnWidths'
import {useDebouncedValue} from '@/features/table/useTableView'

import {ref,reactive,computed,onMounted,watch} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessage} from 'element-plus'
import {useAuthStore} from '@/stores/auth'
import {getResourceTree} from '@/api/resource'
import {ops,listOps,exportSheet,printAssetLabels,usageLabels,errorMessage} from '@/api/asset-ops'
import '@/styles/asset-ops.css'
const auth=useAuthStore(),loading=ref(false),busy=ref(false),devices=ref<any[]>([]),sites=ref<any[]>([]),rooms=ref<any[]>([]),selected=ref<any[]>([])
const route=useRoute()
watch(()=>route.query.category,value=>{filters.category=value==='PC'?'PC':''})
const filters=reactive({search:'',category:route.query.category==='PC'?'PC':'',siteId:'',warranty:''}),dialog=ref(false),current=ref<any>(null),profile=reactive<any>({}),coverageDialog=ref(false),coverage=reactive<any>({})
const canWrite=computed(()=>auth.user?.roles?.some(r=>['system_admin','asset_manager'].includes(r.code)))
async function load(){loading.value=true;try{[devices.value,sites.value]=await Promise.all([listOps('devices'),listOps('sites')]);const tree=await getResourceTree();rooms.value=(tree.items||[]).flatMap((d:any)=>(d.rooms||[]).map((r:any)=>({...r,label:d.name+' / '+r.name})))}catch(e){ElMessage.error(errorMessage(e))}finally{loading.value=false}}
function assetSite(a:any){if(a.device.currentPosition){const p=a.device.currentPosition;return rooms.value.find(r=>r.id===p.roomId)?.label||p.rack?.name||p.roomId}return a.profile.site?.name||'位置待补全'}
const query=useDebouncedValue(()=>filters.search)
const filtered=computed(()=>devices.value.filter(a=>{const d=a.device,p=a.profile,q=query.value.trim().toLowerCase();return (!q||[d.code,d.name,d.serialNumber,d.managementIp,d.modelNumber].some(v=>String(v||'').toLowerCase().includes(q)))&&(!filters.category||d.type?.category===filters.category)&&(!filters.siteId||p.siteId===filters.siteId||(d.currentPosition&&sites.value.find(s=>s.id===filters.siteId)?.roomId===d.currentPosition.roomId))&&(!filters.warranty||a.warranty.status===filters.warranty)}))
const risk=computed(()=>devices.value.filter(a=>a.device.lifecycleStatus!=='SCRAPPED'&&['SOON','EXPIRED','GAP'].includes(a.warranty.status)).length)
const pcCount=computed(()=>devices.value.filter(a=>a.device.type?.category==='PC').length)
function edit(a:any){current.value=a;Object.keys(profile).forEach(k=>delete profile[k]);Object.assign(profile,{version:0,siteId:null,position:'',usageStatus:'IDLE',assignee:'',department:a.device.organization||'',cpu:'',memoryGb:0,disk:'',operatingSystem:'',gpu:'',raid:'',ports:'',environment:'OFFICE',importance:'NORMAL',noWarranty:false},a.profile);dialog.value=true}
async function save(){busy.value=true;try{await ops(`devices/${current.value.device.id}/profile`,'PUT',profile);dialog.value=false;await load();ElMessage.success('资产配置已保存并记录历史')}catch(e){ElMessage.error(errorMessage(e))}finally{busy.value=false}}
function addCoverage(a:any){current.value=a;Object.assign(coverage,{kind:'FACTORY',provider:'',startsOn:'',endsOn:'',contact:'',serviceLevel:''});coverageDialog.value=true}
async function saveCoverage(){busy.value=true;try{await ops(`devices/${current.value.device.id}/coverages`,'POST',{...coverage,startsOn:coverage.startsOn+'T00:00:00+08:00',endsOn:coverage.endsOn+'T00:00:00+08:00'});coverageDialog.value=false;await ops('reminders/refresh','POST');await load();ElMessage.success('服务保障已登记')}catch(e){ElMessage.error(errorMessage(e))}finally{busy.value=false}}
function exportAssets(){exportSheet('资产配置台账',assetSortedRows.value.map(a=>({资产编号:a.device.code,设备名称:a.device.name,类型:a.device.type?.name,SN:a.device.serialNumber,品牌:a.device.manufacturer,型号:a.device.modelNumber,位置:assetSite(a),使用状态:a.device.lifecycleStatus==='SCRAPPED'?'已报废':usageLabels[a.profile.usageStatus]||'待登记',使用人或运维责任人:a.profile.assignee,部门:a.profile.department,CPU:a.profile.cpu,内存GB:a.profile.memoryGb,硬盘:a.profile.disk,系统:a.profile.operatingSystem,显卡:a.profile.gpu,RAID:a.profile.raid,端口:a.profile.ports,IP:a.device.managementIp,保修状态:a.warranty.label,保障截止日:a.warranty.endsOn,已关联部件:a.components.map((p:any)=>p.spec.name+' / SN '+p.serialNumber).join('；')})))}
async function labels(){try{await printAssetLabels('device',selected.value.map(a=>a.device));ElMessage.success('标签已生成，请在标签窗口打印或保存 PDF')}catch(e){ElMessage.error(errorMessage(e))}}
const {page:assetPage,pageSize:assetSize,total:assetTotal,pageRows:assetRows,sortedRows:assetSortedRows,sortKey:assetSortKey,sortOrder:assetSortOrder,tableRef:assetTable,sortBy:sortAssetBy,onSortChange:onAssetSortChange}=useClientTable(filtered,{locationLabel:row=>assetSite(row),configuration:row=>(row.device.type?.category==='NETWORK'?row.profile.ports:row.profile.cpu)||''})
const {columnWidths:assetWidths,resizeColumn:resizeAssetColumn}=useColumnWidths({"device.name": 210, "device.type.name": 180, "locationLabel": 220, "configuration": 230, "warranty.label": 125})
function clearAssetSelection(){assetTable.value?.clearSelection();selected.value=[]}
function clearAssetFilters(){filters.search='';query.value='';filters.category='';filters.siteId='';filters.warranty=''}
watch([assetPage,assetSize,assetSortKey,assetSortOrder,filtered],clearAssetSelection)
const {page:componentPage,pageSize:componentSize,total:componentTotal,pageRows:componentRows,sortedRows:componentSortedRows,sortKey:componentSortKey,sortOrder:componentSortOrder,tableRef:componentTable,sortBy:sortComponentBy,onSortChange:onComponentSortChange}=useClientTable(() => current.value?.components || [],{})
const {columnWidths:componentWidths,resizeColumn:resizeComponentColumn}=useColumnWidths({"spec.name": 160, "serialNumber": 160, "spec.specification": 160})
onMounted(load)
</script>
<template><div class="asset-ops"><div class="ops-heading"><div><span class="ops-eyebrow">IT ASSET OPERATIONS</span><h1>配置与保修中心</h1><p>汇总终端与机房设备的配置和保修，共用同一份设备档案；此处不重复新增资产。</p></div></div><div class="ops-metrics"><div><span>设备总数</span><b>{{devices.length}}<small>台</small></b></div><div><span>终端</span><b>{{pcCount}}<small>台</small></b></div><div><span>设备保修风险</span><b>{{risk}}<small>台</small></b></div><div><span>机房设备</span><b>{{devices.length-pcCount}}<small>台</small></b></div></div><el-card shadow="never" v-loading="loading"><div class="ops-toolbar"><el-input v-model="filters.search" clearable placeholder="编号 / SN / 名称 / IP" @input="clearAssetSelection"/><el-select v-model="filters.category" clearable placeholder="设备分类"><el-option v-for="(v,k) in {PC:'终端',SERVER:'服务器',NETWORK:'网络设备',STORAGE:'存储',SECURITY:'安全设备',OTHER:'其他'}" :key="k" :label="v" :value="k"/></el-select><el-select v-model="filters.siteId" clearable placeholder="资产位置"><el-option v-for="s in sites" :key="s.id" :label="s.region+' / '+s.name" :value="s.id"/></el-select><el-select v-model="filters.warranty" clearable placeholder="保修状态"><el-option v-for="(v,k) in {VALID:'在保',SOON:'即将过保',EXPIRED:'已过保',GAP:'保障空档',UNKNOWN:'信息待补全',NONE:'无保修'}" :key="k" :label="v" :value="k"/></el-select></div><div class="ops-toolbar between"><span class="ops-muted">共 {{filtered.length}} 件 · 此处为配置汇总；新增、领用或上架请进入对应台账</span><div><el-button :disabled="!selected.length||loading||filters.search!==query" @click="labels">打印二维码</el-button><el-button :disabled="loading||filters.search!==query" @click="exportAssets">导出配置台账</el-button></div></div><el-table :data="assetRows" ref="assetTable" @sort-change="onAssetSortChange" @selection-change="selected=$event" row-key="device.id"><el-table-column type="selection" width="45"/><el-table-column label="设备 / 编号" prop="device.name" sortable="custom" :width="assetWidths['device.name']"><template #header><TableSortHeader label="设备 / 编号" :width="assetWidths['device.name']" @sort="sortAssetBy('device.name')" @resize="resizeAssetColumn('device.name',$event)"/></template><template #default="{row}"><b>{{row.device.name}}</b><small class="ops-block ops-mono">{{row.device.code}}</small></template></el-table-column><el-table-column label="类型 / SN" prop="device.type.name" sortable="custom" :width="assetWidths['device.type.name']"><template #header><TableSortHeader label="类型 / SN" :width="assetWidths['device.type.name']" @sort="sortAssetBy('device.type.name')" @resize="resizeAssetColumn('device.type.name',$event)"/></template><template #default="{row}">{{row.device.type?.name}}<small class="ops-block ops-mono">{{row.device.serialNumber||'未登记 SN'}}</small></template></el-table-column><el-table-column label="位置 / 责任人" prop="locationLabel" sortable="custom" :width="assetWidths['locationLabel']"><template #header><TableSortHeader label="位置 / 责任人" :width="assetWidths['locationLabel']" @sort="sortAssetBy('locationLabel')" @resize="resizeAssetColumn('locationLabel',$event)"/></template><template #default="{row}">{{assetSite(row)}}<small class="ops-block ops-muted">{{row.profile.assignee||row.device.manager||'责任人待补全'}}</small></template></el-table-column><el-table-column label="配置摘要" prop="configuration" sortable="custom" :width="assetWidths['configuration']"><template #header><TableSortHeader label="配置摘要" :width="assetWidths['configuration']" @sort="sortAssetBy('configuration')" @resize="resizeAssetColumn('configuration',$event)"/></template><template #default="{row}">{{(row.device.type?.category==='NETWORK'?row.profile.ports:row.profile.cpu)||'配置待补全'}}<small class="ops-block ops-muted">{{row.profile.memoryGb?row.profile.memoryGb+'GB / ':''}}{{row.profile.disk}}</small></template></el-table-column><el-table-column label="保修状态" fixed="right" prop="warranty.label" sortable="custom" :width="assetWidths['warranty.label']"><template #header><TableSortHeader label="保修状态" :width="assetWidths['warranty.label']" @sort="sortAssetBy('warranty.label')" @resize="resizeAssetColumn('warranty.label',$event)"/></template><template #default="{row}"><el-tag :type="row.warranty.status==='VALID'?'success':['EXPIRED','GAP'].includes(row.warranty.status)?'danger':row.warranty.status==='SOON'?'warning':'info'">{{row.warranty.label}}</el-tag></template></el-table-column><el-table-column v-if="canWrite" label="操作" fixed="right" width="155"><template #default="{row}"><el-button link type="primary" @click="edit(row)">配置</el-button><el-button link type="primary" @click="addCoverage(row)">保修 / 维保</el-button></template></el-table-column><template #empty><el-empty description="没有匹配的配置记录"><el-button v-if="query||filters.category||filters.siteId||filters.warranty" @click="clearAssetFilters">清除筛选</el-button></el-empty></template></el-table><TablePager v-model:page="assetPage" v-model:page-size="assetSize" :total="assetTotal" label="配置台账"/></el-card>
<el-dialog v-model="dialog" title="设备资产配置" width="min(850px,95vw)"><p>{{current?.device.code}} · {{current?.device.name}}</p><el-alert v-if="current?.device.type?.category==='PC'" title="终端在用状态、使用人及部门请在 终端管理办理领用/归还/交接；维修、报废和维修完成请在终端管理办理。" :closable="false"/><el-alert v-if="current?.device.currentPosition" title="已上架设备的位置由原机柜流程维护；资产位置如填写，须关联同一机房。" :closable="false"/><el-form label-position="top" class="ops-form-grid"><el-form-item label="资产位置"><el-select v-model="profile.siteId" clearable @clear="profile.siteId=null"><el-option v-for="s in sites" :key="s.id" :label="s.region+' / '+s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="具体位置 / 工位"><el-input v-model="profile.position"/></el-form-item><el-form-item label="使用状态"><el-select v-model="profile.usageStatus" :disabled="current?.device.type?.category==='PC'"><el-option v-for="k in ['IDLE','IN_USE','REPAIR']" :disabled="current?.device.type?.category==='PC' && k==='IN_USE'" :key="k" :label="usageLabels[k]" :value="k"/></el-select></el-form-item><el-form-item label="使用人 / 运维责任人"><el-input v-model="profile.assignee" :disabled="current?.device.type?.category==='PC'"/></el-form-item><el-form-item label="部门"><el-input v-model="profile.department" :disabled="current?.device.type?.category==='PC'"/></el-form-item><el-form-item label="运行环境"><el-select v-model="profile.environment"><el-option v-for="(v,k) in {OFFICE:'办公',PRODUCTION:'生产',TEST:'测试',DR:'灾备'}" :key="k" :label="v" :value="k"/></el-select></el-form-item><el-form-item v-for="[k,l] in [['cpu','CPU 型号及数量'],['disk','硬盘明细（容量、接口、数量）'],['operatingSystem','操作系统'],['gpu','显卡'],['raid','RAID 配置'],['ports','端口与速率']]" :key="k" :label="l"><el-input v-model="profile[k]"/></el-form-item><el-form-item label="内存容量（GB）"><el-input-number v-model="profile.memoryGb" :min="0" :precision="0"/></el-form-item><el-form-item label="服务说明"><el-checkbox v-model="profile.noWarranty">明确无保修服务</el-checkbox></el-form-item></el-form><h3 class="ops-section-title">已关联的按件部件</h3><el-table :data="componentRows" ref="componentTable" @sort-change="onComponentSortChange"><el-table-column label="部件" prop="spec.name" sortable="custom" :width="componentWidths['spec.name']"><template #header><TableSortHeader label="部件" :width="componentWidths['spec.name']" @sort="sortComponentBy('spec.name')" @resize="resizeComponentColumn('spec.name',$event)"/></template><template #default="{row}">{{row.spec.name}}</template></el-table-column><el-table-column label="SN" prop="serialNumber" sortable="custom" :width="componentWidths['serialNumber']"><template #header><TableSortHeader label="SN" :width="componentWidths['serialNumber']" @sort="sortComponentBy('serialNumber')" @resize="resizeComponentColumn('serialNumber',$event)"/></template></el-table-column><el-table-column label="规格" prop="spec.specification" sortable="custom" :width="componentWidths['spec.specification']"><template #header><TableSortHeader label="规格" :width="componentWidths['spec.specification']" @sort="sortComponentBy('spec.specification')" @resize="resizeComponentColumn('spec.specification',$event)"/></template><template #default="{row}">{{row.spec.specification}}</template></el-table-column></el-table><TablePager v-model:page="componentPage" v-model:page-size="componentSize" :total="componentTotal" label="关联部件"/><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存配置</el-button></template></el-dialog>
<el-dialog v-model="coverageDialog" title="登记保修 / 第三方维保" width="min(620px,95vw)"><div v-for="c in current?.coverages||[]" :key="c.id" class="ops-coverage"><b>{{c.provider}}</b> · {{c.kind==='FACTORY'?'原厂保修':'第三方维保'}}<small>{{c.startsOn.slice(0,10)}} 至 {{c.endsOn.slice(0,10)}}</small></div><el-form label-position="top"><el-form-item label="类型"><el-select v-model="coverage.kind"><el-option label="原厂保修" value="FACTORY"/><el-option label="第三方维保" value="THIRD_PARTY"/></el-select></el-form-item><el-form-item label="服务商"><el-input v-model="coverage.provider"/></el-form-item><div class="ops-form-grid"><el-form-item label="开始日期"><el-date-picker v-model="coverage.startsOn" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="截止日期"><el-date-picker v-model="coverage.endsOn" value-format="YYYY-MM-DD"/></el-form-item></div><el-form-item label="联系方式"><el-input v-model="coverage.contact"/></el-form-item><el-form-item label="服务响应约定"><el-input v-model="coverage.serviceLevel"/></el-form-item></el-form><template #footer><el-button type="primary" :loading="busy" @click="saveCoverage">登记服务</el-button></template></el-dialog>
</div></template>

